package password

import (
	"encoding/base64"
	"encoding/json"
	"os"
	"strings"
	"testing"
)

// Generated by the existing Chess Studio Python auth compatibility harness.
// All passwords and salts are synthetic. No production data is committed.
func TestPythonPasswordParityCorpus(t *testing.T) {
	raw, err := os.ReadFile("testdata/python_password_corpus.json")
	if err != nil {
		t.Fatal(err)
	}
	var corpus struct {
		Rows []struct {
			Hash   string `json:"hash"`
			Checks []struct {
				Candidate string `json:"candidate"`
				OK        bool   `json:"ok"`
			} `json:"checks"`
		} `json:"rows"`
	}
	if err := json.Unmarshal(raw, &corpus); err != nil {
		t.Fatal(err)
	}
	total, approved := 0, 0
	for i, row := range corpus.Rows {
		for j, check := range row.Checks {
			total++
			got := Verify(check.Candidate, row.Hash)
			if got != check.OK {
				t.Errorf("Python parity mismatch for row %d check %d (hash type %.10s): got %v want %v", i, j, row.Hash, got, check.OK)
			}
			if got {
				approved++
			}
		}
	}
	if total != 197 || approved < 40 {
		t.Fatalf("missing Python compatibility fixtures: %d checks, %d accepted", total, approved)
	}
}

func TestArgon2idEmissionCompatibleWithPython(t *testing.T) {
	raw, err := os.ReadFile("testdata/python_password_corpus.json")
	if err != nil {
		t.Fatal(err)
	}
	var corpus struct {
		Rows []struct {
			Hash   string `json:"hash"`
			Checks []struct {
				Candidate string `json:"candidate"`
			} `json:"checks"`
		} `json:"rows"`
	}
	if err := json.Unmarshal(raw, &corpus); err != nil {
		t.Fatal(err)
	}
	matched := 0
	for _, row := range corpus.Rows {
		if !strings.HasPrefix(row.Hash, "$argon2id$v=19$m=19456,t=2,p=1$") || len(row.Checks) < 2 {
			continue
		}
		parts := strings.Split(row.Hash, "$")
		salt, err := base64.RawStdEncoding.DecodeString(parts[4])
		if err != nil {
			t.Fatal(err)
		}
		if got := encodeArgon2id(row.Checks[0].Candidate, salt); got != row.Hash {
			t.Fatal("Argon2id output differs from Python corpus")
		}
		matched++
	}
	if matched < 5 {
		t.Fatalf("only %d Python hash vectors verified", matched)
	}
	fresh, err := HashNew("ñandú-♞-2026")
	if err != nil || !Verify("ñandú-♞-2026", fresh) || Verify("wrong", fresh) {
		t.Fatal("new Argon2id hash cannot be safely verified")
	}
	if first, _ := HashNew("same password"); first == fresh {
		t.Fatal("random salt reused")
	}
	for _, candidate := range []string{"", strings.Repeat("x", 4097)} {
		if _, err := HashNew(candidate); err == nil {
			t.Fatal("accepted invalid new password size")
		}
	}
}

func TestMaliciousPHCHashParametersRejectedBeforeKDF(t *testing.T) {
	valid, err := HashNew("test")
	if err != nil {
		t.Fatal(err)
	}
	tests := []string{
		strings.Replace(valid, "m=19456", "m=4294967295", 1),
		strings.Replace(valid, "t=2", "t=4294967295", 1),
		strings.Replace(valid, "p=1", "p=255", 1),
		strings.Replace(valid, "m=19456", "m=1", 1),
		strings.Replace(valid, "t=2", "t=0", 1),
		strings.Replace(valid, "p=1", "p=0", 1),
		strings.Replace(valid, "m=19456", "m=19456,m=19456", 1),
		strings.Replace(valid, "m=19456", "x=19456", 1),
		strings.Replace(valid, "argon2id", "argon2d", 1),
		strings.Replace(valid, "v=19", "v=18", 1),
		strings.Replace(valid, "$", "", 1),
		strings.Repeat("A", 257),
		"$2b$31$tnOPDpHJb2Z4/Htxd9uS4Og6iiJtlLo443XmzZ1Lt3wRAJXmgxgRS",
		"$2b$04$short",
		"$1$md5$test",
	}
	for i, hash := range tests {
		if Verify("test", hash) {
			t.Errorf("accepted malicious hash vector %d", i)
		}
	}
	if Verify(strings.Repeat("x", 4097), valid) {
		t.Fatal("unbounded candidate accepted")
	}
}
